\cite{fang2026invariantII}
	\label{thm:1.1}
	The following two statements are equivalent.
	\begin{enumerate}
		\item For any invertible operator $T\in\mathcal{B}(\mathcal{H})$ with a nontrivial invariant subspace, $T^{-1}$ has a nontrivial invariant subspace.
		
		\item For any invertible operator $T\in\mathcal{B}(\mathcal{H})$ with a conjugate bi‑geometric form, $T^{-1}$ has a nontrivial invariant subspace.
	\end{enumerate}

\label{def:2.3}\cite{douglas1998}
	Let $\mathcal{H}$ be a Hilbert space. An operator $T\in\mathcal{B}(\mathcal{H})$ is said to be a \textit{Fredholm operator} if $\pi(T)$ is invertible in the Calkin algebra $\mathcal{B}(\mathcal{H})/\mathcal{K}(\mathcal{H})$.
	Let $\mathcal{F}(\mathcal{H})$ stand for the set of all Fredholm operators on $\mathcal{H}$.

\label{def:1.1}\cite{fang2026invariantII}
	Let $T\in\mathcal{B}(\mathcal{H})$. We say that $T$ has a \textit{conjugate bi‑geometric form}, if there is a nontrivial subspace $M$ such that
	\[
	T=
	\begin{pmatrix}
		T_1 & T_{12}\\
		0 & T_2
	\end{pmatrix}\!\!\!\!
	\begin{matrix}
		M\\
		\ \ M^{\perp}
	\end{matrix}
	\]
	where $T_1^*, T_2\in B_1(O_\delta)$ and $O_\delta\triangleq\{z\in\mathbb{C};\,|z|<\delta\}$ for some $\delta>0$.

\cite{IJMJjiang2025cowen}
		Let \(A\in B(\mathcal H)\), and let \(\{e_n\}_{n=0}^\infty\) be an orthonormal basis for \(\mathcal H\). If \(AB=I\) and\[
\langle B e_j, e_i\rangle =
\begin{cases}
	0, & i=0,\\[2mm]
	b_{i,\,j}, & i\ge 1,
\end{cases}
\qquad j\ge 0.
\]	then \(B\) is called a \textit{standard right inverse} of \(A\).
	
	Similarly, if \(C^{*}\) is a standard right inverse of \(A^{*}\), then \(C\) is called a \textit{standard left inverse} of \(A\).

\cite{cowen1983operators}
	Let $\mathscr{B}_{m,n}(\Omega)$ denote the class of bounded linear operators on $\mathscr{H}$ defined by
    
                                                                
                 
                                                                                                     
                                                                                                                  
                                                               
	                                                          
                                                                                       
               
    


$	\mathscr{B}_{m,n}(\Omega)
	=\bigl\{T\in\mathscr{L}(\mathcal{H}):$
	\begin{align*}
		&(1)\ \dim\ker(T-\omega)=m \text{ and } \dim\ker(T-\omega)^{*}=n \text{ for all } \omega\in\Omega;\\
		&(2)\ (T-\omega)\mathcal{H} \text{ and } (T-\omega)^{*}\mathcal{H} \text{ are closed for all } \omega\in\Omega;\\
		 &(3)\ \mathcal{M}_T+\mathcal{N}_T=\mathcal{H},\ \text{where }
		\mathcal{M}_T=\bigvee_{\omega\in\Omega}\ker(T-\omega),\\
		&\mathcal{N}_T=\bigvee_{\omega\in\Omega}(\ker(T-\omega)^{*})\bigr\}.
	\end{align*}

\label{rem:2.7}
	For
	\[
	T=\begin{pmatrix}
		T_1 & X\\
		0 & T_2
	\end{pmatrix},\quad
	\tilde{T}=\begin{pmatrix}
		\tilde{T}_1 & \tilde{X}\\
		0 & \tilde{T}_2
	\end{pmatrix}\in B_{1,1}(\Omega).
	\]
	
	Let $P_i(w)$ be the orthogonal projection onto $\ker(T - w)^i$ for $i=1,2$, and $Q_j(w)$ the orthogonal projection onto $\ker((T - w)^*)^{j}$ for $j=1,2$. Let $\gamma(w)$ and $\delta(w)$ be sections spanning $\ker(T - w)$ and $\ker(T^* - w)$, respectively. Then we have the following conclusion:

	
	If $T_1\sim_u \tilde{T}_1$ and $T_2\sim_u \tilde{T}_2$, then $T\sim_u \tilde{T}$ if and only if
	\[
	\frac{|\langle \gamma(\omega_1), X\delta(\overline{\omega}_2)\rangle|}
	{\|\gamma(\omega_1)\|\,\|\delta(\overline{\omega}_2)\|}
	=
	\frac{|\langle \tilde{\gamma}(\omega_1), \tilde{X}\tilde{\delta}(\overline{\omega}_2)\rangle|}
	{\|\tilde{\gamma}(\omega_1)\|\,\|\tilde{\delta}(\overline{\omega}_2)\|}
	\]
	for all $\omega_1,\omega_2\in O_\delta$ \cite{cowen1983operators}.

\label{def:2.8}
	Let
	\[
	T=\begin{pmatrix}
		A & T_{12}\\
		0 & B
	\end{pmatrix}\in B(M\oplus M^{\perp}),
	\]
	where $A^{*},B\in B_1(O_\delta)$.
	Define its \textit{induced operator}
	\[
	S=\begin{pmatrix}
		S_1 & X\\
		0 & S_2
	\end{pmatrix}
	=\begin{pmatrix}
		A^{*} & T_{12}\\
		0 & B^{*}
	\end{pmatrix}.
	\]

\label{lem:3.5}
	For $\{A^n e_0'\}_{n=0}^{\infty}$, there exists a sequence $\{g_n\}_{n=0}^{\infty}\subset \bigvee_{n\ge 0}\{A^{n}e_{0}^{\prime}\}$ such that $\langle A^{n}e_{0}^{\prime}, g_{m}\rangle=\delta_{n,m}$, where $\delta_{n,m}=
	\begin{cases}
		1,& n=m\\
		0,& n\neq m
	\end{cases}$.

Let \(T = \begin{pmatrix} S & T_{12} \\ 0 & S^* \end{pmatrix}\). Suppose there exists \(K \in B(H^2)\) satisfying the following conditions:
 	\begin{enumerate}
 		\item[(1)] \(\sum_{j=0}^n k_{j,n-j} = 0\) for all \(n \geq 0\);
 		\item[(2)] \(A_N(K) = \sum_{r=0}^N (S^*)^{r+1} K (S^*)^r\) is uniformly bounded;
 		\item[(3)] \(\lim_{n \to \infty} \|(S^*)^n K\| = 0\).
 	\end{enumerate}
 	If \(\tilde{T} = \begin{pmatrix} S & T_{12} - K \\ 0 & S^* \end{pmatrix}\) has the bundle-preserving property, then \(T\) is essentially unitary and \(T^{-1}\) is intransitive.

\label{4.1}
 	Let
 	\[
 	T=\begin{pmatrix}
 		A & T_{12}\\
 		0 & B
 	\end{pmatrix}\in B(\mathcal{H}_{1}\oplus \mathcal{H}_{2}),\quad
 	\tilde{T}=\begin{pmatrix}
 		\tilde{A} & \tilde{A}_{12}\\
 		0 & \tilde{B}
 	\end{pmatrix}\in B(\tilde{\mathcal{H}}_{1}\oplus \tilde{\mathcal{H}_{2}}),
 	\]
 	where $A^{*},B,\tilde{A}^{*},\tilde{B}\in B_{1}(O_{\delta})$. Let $S$ and $\tilde{S}$ be the induced operators of $T$ and $\tilde{T}$, respectively. If $S\sim_{X}\tilde{S}$, then
 	\[
 	X=\begin{pmatrix}
 		X_{1} & X_{12}\\
 		0 & X_{2}
 	\end{pmatrix},
 	\]
 	and $A\sim_{s}\tilde{A}$, $B\sim_{s}\tilde{B}$.

Note that
 	\[
 	S=\begin{pmatrix}
 		A^{*} & T_{12}\\
 		0 & B^{*}
 	\end{pmatrix},\quad
 	\tilde{S}=\begin{pmatrix}
 		\tilde{A}^{*} & \tilde{A}_{12}\\
 		0 & \tilde{B}^{*}
 	\end{pmatrix}.
 	\]
 	Since
 	\[
 	\begin{pmatrix}
 		X_{1} & X_{12}\\
 		X_{21} & X_{2}
 	\end{pmatrix}
 	\begin{pmatrix}
 		A^{*} & T_{12}\\
 		0 & B^{*}
 	\end{pmatrix}
 	=
 	\begin{pmatrix}
 		\tilde{A}^{*} & \tilde{A}_{12}\\
 		0 & \tilde{B}^{*}
 	\end{pmatrix}
 	\begin{pmatrix}
 		X_{1} & X_{12}\\
 		X_{21} & X_{2}
 	\end{pmatrix},
 	\]
 	we obtain $X_{21}A^{*}=\tilde{B}^{*}X_{21}$. Hence
 	$X_{21}(A^{*}-w)=(\tilde{B}^{*}-w)X_{21}$, so
 	\[
 	X_{21}\ker(A^{*}-w)\subset \ker(\tilde{B}^{*}-w).
 	\]
 	Note that $\sigma_{p}(B^{*})=\emptyset$.
 	Thus $X_{21}e_{A^{*}}(w)=0$, which implies $X_{21}=0$. Consequently,
 	\[
 	X=\begin{pmatrix}
 		X_{1} & X_{12}\\
 		0 & X_{2}
 	\end{pmatrix}.
 	\]
 	
 	Let $Y=X^{-1}$. Then $SY=Y\tilde{S}$. A similar calculation shows that
 	 $Y_{21}=0$, so
 	\[
 	Y=\begin{pmatrix}
 		Y_{1} & Y_{12}\\
 		0 & Y_{2}
 	\end{pmatrix}.
 	\]

 	Since $XY=YX=I$, we have
 	\[
 	\begin{pmatrix}
 		X_{1} & X_{12}\\
 		0 & X_{2}
 	\end{pmatrix}
 	\begin{pmatrix}
 		Y_{1} & Y_{12}\\
 		0 & Y_{2}
 	\end{pmatrix}
 	=
 	\begin{pmatrix}
 		I & 0\\
 		0 & I
 	\end{pmatrix},
 	\]
 	\[
 	\begin{pmatrix}
 		Y_{1} & Y_{12}\\
 		0 & Y_{2}
 	\end{pmatrix}
 	\begin{pmatrix}
 		X_{1} & X_{12}\\
 		0 & X_{2}
 	\end{pmatrix}
 	=
 	\begin{pmatrix}
 		I & 0\\
 		0 & I
 	\end{pmatrix}.
 	\]
 	Therefore,
 	\[
 	\begin{cases}
 		X_{1}Y_{1}=Y_{1}X_{1}=I\\
 		X_{2}Y_{2}=Y_{2}X_{2}=I
 	\end{cases},
 	\]
 	so $X_{1},Y_{1},X_{2},Y_{2}$ are invertible. Since
 	\[
 	\begin{cases}
 		X_{1}A^{*}=\tilde{A}^{*}X_{1}\\
 		X_{2}B^{*}=\tilde{B}^{*}X_{2}
 	\end{cases},
 	\]
 	we obtain
 	\[
 	\begin{cases}
 		A X_{1}^{*}=X_{1}^{*}\tilde{A}\\
 		B X_{2}^{*}=X_{2}^{*}\tilde{B}
 	\end{cases}.
 	\]
 	Hence $A\sim_{s}\tilde{A}$, $B\sim_{s}\tilde{B}$.

For the operators in Lemma \ref{4.1}, we have
 	\[
 	\begin{pmatrix}
 		A^{*} & 0\\
 		T_{12}^{*} & B^{*}
 	\end{pmatrix}
 	\begin{pmatrix}
 		X_{1}^{*} & 0\\
 		X_{12}^{*} & X_{2}^{*}
 	\end{pmatrix}
 	=
 	\begin{pmatrix}
 		A^{*}X_{1}^{*} & 0\\
 		T_{12}^{*}X_{1}^{*}+B^{*}X_{12}^{*} & B^{*}X_{2}^{*}
 	\end{pmatrix},
 	\]
 	\[
 	\begin{pmatrix}
 		X_{1}^{*} & 0\\
 		X_{12}^{*} & X_{2}^{*}
 	\end{pmatrix}
 	\begin{pmatrix}
 		\tilde{A}^{*} & 0\\
 		\tilde{A}_{12}^{*} & \tilde{B}^{*}
 	\end{pmatrix}
 	=
 	\begin{pmatrix}
 		X_{1}^{*}\tilde{A}^{*} & 0\\
 		X_{12}^{*}\tilde{A}^{*}+X_{2}^{*}\tilde{A}_{12}^{*} & X_{2}^{*}\tilde{B}^{*}
 	\end{pmatrix}.
 	\]
 	Thus, the equality
 	\[
 	\begin{pmatrix}
 		A^{*} & 0\\
 		T_{12}^{*} & B^{*}
 	\end{pmatrix}
 	\begin{pmatrix}
 		X_{1}^{*} & 0\\
 		X_{12}^{*} & X_{2}^{*}
 	\end{pmatrix}
 	=
 	\begin{pmatrix}
 		X_{1}^{*} & 0\\
 		X_{12}^{*} & X_{2}^{*}
 	\end{pmatrix}
 	\begin{pmatrix}
 		\tilde{A}^{*} & 0\\
 		\tilde{A}_{12}^{*} & \tilde{B}^{*}
 	\end{pmatrix}
 	\]
 	does not necessarily hold. Consequently,
 	\[
 	\begin{pmatrix}
 		A & T_{12}\\
 		0 & B
 	\end{pmatrix}
 	\sim
 	\begin{pmatrix}
 		\tilde{A} & \tilde{A}_{12}\\
 		0 & \tilde{B}
 	\end{pmatrix}
 	\]
 	may fail in general. Therefore, the similarity of induced operators of conjugate bi-geometric operators does not imply the similarity of the original conjugate bi-geometric operators.
